import { parseStreaming } from '@redwood/tsdk/streaming';
import { isToolResponse, ToolResponseZ, streamingShapeHints } from './generated/runtime';

// streaming parser receives chunked tokens from the API
const parser = parseStreaming(streamSource, { shapeHints: streamingShapeHints });
for await (const partial of parser) {
  // partial may contain object fragments; parser will use hints to early-detect discriminant
  if (partial.kindHint === 'error') {
    // quick early handling
    console.warn('early error hint', partial);
  }
}

// full message validation when object completes
const payload = await parser.nextCompleteObject();
if (isToolResponse(payload)) {
  // fast path
} else {
  // fallback to Zod for detailed errors
  const result = ToolResponseZ.safeParse(payload);
  if (!result.success) throw new Error('schema mismatch');
}
